-- Four more industries (erp/industries.py): restaurants & cafés, professional services, manufacturing & workshops,
-- transport & logistics. Their starter sections are the ERP's template for each (every section minus the ones it hides).
-- Added only where the owner has not set that industry already; nothing else in the console's list changes.
update public.billing_config
   set core_by_industry = '{"restaurant": {"name": "Restaurants & cafés", "name_ar": "المطاعم والكافيهات", "modules": ["dashboard", "crm", "business_units", "sales", "shop", "purchasing", "stock", "payroll", "assets", "accounting", "partners", "reports", "tax", "import_export", "settings", "users", "team"]}, "services": {"name": "Professional services & consulting", "name_ar": "الخدمات المهنية والاستشارات", "modules": ["dashboard", "crm", "business_units", "projects", "sales", "purchasing", "payroll", "assets", "accounting", "partners", "reports", "tax", "import_export", "settings", "users", "team"]}, "manufacturing": {"name": "Manufacturing & workshops", "name_ar": "التصنيع والورش", "modules": ["dashboard", "crm", "business_units", "projects", "contracts", "sales", "shop", "purchasing", "stock", "equipment", "payroll", "assets", "accounting", "partners", "reports", "tax", "import_export", "settings", "users", "team"]}, "logistics": {"name": "Transport & logistics", "name_ar": "النقل والخدمات اللوجستية", "modules": ["dashboard", "crm", "business_units", "projects", "sales", "purchasing", "stock", "equipment", "rentals", "payroll", "assets", "accounting", "partners", "reports", "tax", "import_export", "settings", "users", "team"]}}'::jsonb || core_by_industry
 where id = 1;
